      expect(body[1].expression.left.properties[0]).toStrictEqual(
        renamedPropertyMatcher,
      );
      expect(body[2].expression.right.properties[0]).toStrictEqual(
        renamedPropertyMatcher,
      );

      expect(String(program)).toMatchInlineSnapshot(`
        "const {
          a: _a
        } = b;
        ({
          a: _a
        } = b);
        c = {
          a: _a
        };"
      `);
    });

